cat << 'EOF' > fix-specs.js
const fs = require('fs');
const path = require('path');

const testFile = fs.readFileSync('src/transport/ws/messageHandler.test.ts', 'utf8').split('\n');
const specsDir = 'specs';

function walk(dir) {
    let results = [];
    const list = fs.readdirSync(dir);
    list.forEach(file => {
        file = path.join(dir, file);
        const stat = fs.statSync(file);
        if (stat && stat.isDirectory()) {
            results = results.concat(walk(file));
        } else if (file.endsWith('spec.md')) {
            results.push(file);
        }
    });
    return results;
}

const specs = walk(specsDir);

specs.forEach(spec => {
    let content = fs.readFileSync(spec, 'utf8');
    let changed = false;

    // Fix off-by-1 links
    content = content.replace(/src\/transport\/ws\/messageHandler\.test\.ts#L(\d+)/g, (match, p1) => {
        const line = parseInt(p1, 10);
        const targetLine = testFile[line - 1] || '';
        if (targetLine.trim() === '' || targetLine.trim() === '});') {
            const nextLine = testFile[line] || '';
            if (nextLine.trim().startsWith('it(')) {
                changed = true;
                return `src/transport/ws/messageHandler.test.ts#L${line + 1}`;
            }
        }
        return match;
    });

    if (changed) {
        fs.writeFileSync(spec, content);
        console.log(`Updated ${spec}`);
    }
});
EOF
